#include <iostream>
#include <stack>
#include <string>

class BrowserHistory {
public:
    explicit BrowserHistory(const std::string& homepage) {
        history_.push(homepage);
    }

    void visit(const std::string& url) {
        history_.push(url);
        future_ = std::stack<std::string>();
    }

    std::string back(int steps) {
        while (steps > 0 && history_.size() > 1) {
            future_.push(history_.top());
            history_.pop();
            steps--;
        }
        return history_.top();
    }

    std::string forward(int steps) {
        while (steps > 0 && !future_.empty()) {
            history_.push(future_.top());
            future_.pop();
            steps--;
        }
        return history_.top();
    }

private:
    std::stack<std::string> history_; // the pages behind you, the current page on top
    std::stack<std::string> future_;  // the pages ahead of you, the next one on top
};

int main() {
    std::string homepage;
    int q;
    std::cin >> homepage >> q;
    BrowserHistory browser(homepage);
    for (int i = 0; i < q; i++) {
        std::string op, url;
