import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        BrowserHistory browser = new BrowserHistory(in.next());
        int q = in.nextInt();
        for (int i = 0; i < q; i++) {
            String op = in.next();
            if (op.equals("visit")) {
                browser.visit(in.next());
            } else if (op.equals("back")) {
                System.out.println(browser.back(in.nextInt()));
            } else {
                System.out.println(browser.forward(in.nextInt()));
            }
        }
    }
}

class BrowserHistory {
    private final Deque<String> history = new ArrayDeque<>(); // the current page on top
    private final Deque<String> future = new ArrayDeque<>(); // the next page on top

    BrowserHistory(String homepage) {
        history.push(homepage);
    }

    void visit(String url) {
        history.push(url);
        future.clear();
    }

    String back(int steps) {
        while (steps > 0 && history.size() > 1) {
            future.push(history.pop());
            steps--;
        }
        return history.peek();
    }

    String forward(int steps) {
        while (steps > 0 && !future.isEmpty()) {
            history.push(future.pop());
            steps--;
        }
        return history.peek();
    }
}

