package main

import "fmt"

// BrowserHistory is one browser tab's history of pages.
type BrowserHistory struct {
	history []string // the pages behind you, the current page on top
	future  []string // the pages ahead of you, the next one on top
}

func newBrowserHistory(homepage string) *BrowserHistory {
	return &BrowserHistory{history: []string{homepage}}
}

func (b *BrowserHistory) visit(url string) {
	b.history = append(b.history, url)
	b.future = b.future[:0]
}

func (b *BrowserHistory) back(steps int) string {
	for ; steps > 0 && len(b.history) > 1; steps-- {
		top := b.history[len(b.history)-1]
		b.history = b.history[:len(b.history)-1]
		b.future = append(b.future, top)
	}
	return b.history[len(b.history)-1]
}

func (b *BrowserHistory) forward(steps int) string {
	for ; steps > 0 && len(b.future) > 0; steps-- {
		top := b.future[len(b.future)-1]
		b.future = b.future[:len(b.future)-1]
		b.history = append(b.history, top)
	}
	return b.history[len(b.history)-1]
}

